": 0, "credit_id": "570d76c892514124e800007a", "department": "Directing", "popularity": 0.0441, "profile_path": null, "original_name": "Ira Hurvitz", "known_for_department": "Directing"}, {"id": 1604955, "job": "Costume Design", "name": "Cathy Crandall", "adult": false, "gender": 0, "credit_id": "570d7283c3a3680a39000002", "department": "Costume & Make-Up", "popularity": 0.1973, "profile_path": null, "original_name": "Cathy Crandall", "known_for_department": "Costume & Make-Up"}, {"id": 2151, "job": "Casting", "name": "Amy Lippens", "adult": false, "gender": 1, "credit_id": "570d721b92514114e000011f", "department": "Production", "popularity": 0.1964, "profile_path": null, "original_name": "Amy Lippens", "known_for_department": "Production"}, {"id": 12256, "job": "Unit Production Manager", "name": "Gerrit van der Meer", "adult": false, "gender": 2, "credit_id": "570d71f7c3a3687352000173", "department": "Production", "popularity": 0.1226, "profile_path": null, "original_name": "Gerrit van der Meer", "known_for_department": "Production"}, {"id": 1493983, "job": "Original Music Composer", "name": "Jon Ehrlich", "adult": false, "gender": 2, "credit_id": "570d716a92514114d800011a", "department": "Sound", "popularity": 0.0516, "profile_path": null, "original_name": "Jon Ehrlich", "known_for_department": "Sound"}, {"id": 1604953, "job": "Original Music Composer", "name": "Jason Derlatka", "adult": false, "gender": 2, "credit_id": "570d712892514114e500014f", "department": "Sound", "popularity": 0.0495, "profile_path": null, "original_name": "Jason Derlatka", "known_for_department": "Sound"}, {"id": 41424, "job": "Executive Producer", "name": "Katie Jacobs", "adult": false, "gender": 1, "credit_id": "5256ccff19c2956ff607d47e", "department": "Production", "popularity": 0.1325, "profile_path": null, "original_name": "Katie Jacobs", "known_for_department": "Production"}, {"id": 9032, "job": "Executive Producer", "name": "Bryan Singer", "adult": false, "gender": 2, "credit_id": "5256ccff19c2956ff607d3f6", "department": "Production", "popularity": 0.5196, "profile_path": "/to8mWJabPoWkphkbYKoutCVSj06.jpg", "original_name": "Bryan Singer", "known_for_department": "Directing"}, {"id": 45543, "job": "Executive Producer", "name": "Paul Attanasio", "adult": false, "gender": 2, "credit_id": "5256ccff19c2956ff607d2e4", "department": "Production", "popularity": 0.809, "profile_path": "/4KtcNH1Tu7CiiMJGXPSOlINhpmR.jpg", "original_name": "Paul Attanasio", "known_for_department": "Writing"}, {"id": 169061, "job": "Executive Producer", "name": "David Shore", "adult": false, "gender": 2, "credit_id": "5256ccfe19c2956ff607d14e", "department": "Production", "popularity": 0.8623, "profile_path": "/5xVWN3KCGtGjGkEIrHqHrx8UikG.jpg", "original_name": "David Shore", "known_for_department": "Writing"}]}, "seasons": [{"id": 3682, "name": "Specials", "air_date": "2011-02-10", "overview": "", "poster_path": "/4qDffrHMZRjSqiR3mVmzvAkhh54.jpg", "vote_average": 0, "episode_count": 46, "season_number": 0}, {"id": 3674, "name": "Season 1", "air_date": "2004-11-16", "overview": "Dr. Gregory House is devoid of bedside manner  and wouldn't even talk to his patients if he could get away with it.  Dealing with his own constant physical pain, he uses a cane that seems  to punctuate his acerbic, brutally honest demeanor. While his behavior  can border on antisocial, House is a maverick physician whose  unconventional thinking and flawless instincts have afforded him a great  deal of respect. House's roster of medical cases are the inexplicable  ones other doctors can't solve, and he has assembled an elite team of  young medical experts to help him in his effort to solve these  diagnostic mysteries.", "poster_path": "/lXBIhFheyDRA72vRQvYF1mkEF27.jpg", "vote_average": 7.8, "episode_count": 22, "season_number": 1}, {"id": 3675, "name": "Season 2", "air_date": "2005-09-13", "overview": "House will do whatever it takes to solve a  case before it's too late, from sending one of his team to break into a  patient's home in search of clues, to attempting a controversial,  trial-and-error form of treatment to see how a patient responds. House's  methods may be suspect, but his results are not — he saves lives no one  else can. Always in House's way is Dr. Lisa Cuddy, the Dean of Medicine  and hospital administrator — and ethical gatekeeper of the hospital who  is in constant conflict with House over his extreme treatments and  unconventional behavior. House's former love Stacy Warner recently  accepted a job as General Counsel to the hospital, and her presence  there has reignited feelings House thought were safely buried.", "poster_path": "/j2LxTsMhXYqfi4k9Vome8kQc26U.jpg", "vote_average": 7.8, "episode_count": 24, "season_number": 2}, {"id": 3679, "name": "Season 3", "air_date": "2006-09-05", "overview": "In the Season 2 finale, House suffered  multiple gunshot wounds inflicted by a former patient's husband  determined to carry out retribution for House's treatment of his wife's  case. In a shocking surprise to his co-workers, House comes through the  ordeal with a slightly new perspective on his treatment of patients —  but will it affect how he makes medical decisions? And will it last?", "poster_path": "/muuLevUfVbpq87lWljfZ8HLga6b.jpg", "vote_average": 7.8, "episode_count": 24, "season_number": 3}, {"id": 3678, "name": "Season 4", "air_date": "2007-09-25", "overview": "In the Season 3 finale, the set-in-his-ways House was confronted  with a series of major changes to his team — but any effects of this  “house-cleaning,\\" or the changes it may bring to House professionally or  personally, remain to be seen...", "poster_path": "/CryJFbwif5U1VViZ5EkmeomD3q.jpg", "vote_average": 8, "episode_count": 16, "season_number": 4}, {"id": 3676, "name": "Season 5", "air_date": "2008-09-16", "overview": "In the Season 4 finale, after a massive bus accident left House without  recollection of the accident, he and  the team put the pieces of his  memory together and discover Wilson’s girlfriend Amber was on the bus  with him and was fatally injured.  Wilson has to face the shocking  realization that House was involved in Amber’s death.\\n\\nAs Season 5  opens, with his friendship with Wilson shattered, House must determine  if he’s responsible for Amber’s death and Wilson must decide if House is  a destructive force in his life while Cuddy attempts to advance a  reconciliation between the two of them.", "poster_path": "/bwE3QGVeC7E5VycnIPVzPtzpBId.jpg", "vote_average": 7.9, "episode_count": 24, "season_number": 5}, {"id": 3677, "name": "Season 6", "air_date": "2009-09-21", "overview": "When the previous season concluded, House was  forced to admit that he had lost his grip on reality and could no longer  practice medicine.  Out of options, he checked himself into a  psychiatric hospital. Season 6 will explore  House’s long and twisted road to recovery: Can he find some version of  sanity and normalcy? Can he stay away from the workplace that arguably  drove him to mental instability but is also the only stable foundation  in his life? Can Princeton-Plainsboro continue its celebrated Department  of Diagnostics without him? How will Cuddy’s relationship with House  change, now that their imagined affair is out in the open?", "poster_path": "/hhcJGHhq2xMUCp2sGRrw523M7Zx.jpg", "vote_average": 8, "episode_count": 21, "season_number": 6}, {"id": 3680, "name": "Season 7", "air_date": "2010-09-20", "overview": "In the Season 6 finale, House, driven by the  loss of a patient he treated at an accident site and confronted with  the unexpected news that Cuddy was now engaged, spiraled into despair  and considered treating his mental and emotional anguish with Vicodin,  potentially prompting the cycle of his dependency and addiction all over  again. But in a surprising turn, Cuddy revealed that she called off her  engagement and admitted to House she loves him, despite wishing she  didn’t. Also, Thirteen submitted her leave of absence from the hospital,  prompting questions about the status of her health.  As Season 7 begins, House and Cuddy attempt to make a real  relationship work and face the question as to whether their new  relationship will affect their ability to diagnose patients.", "poster_path": "/x62Ii2v8fZer0jhpT4w9ngdUE4j.jpg", "vote_average": 8, "episode_count": 23, "season_number": 7}, {"id": 3681, "name": "Season 8", "air_date": "2011-10-03", "overview": "Last season, House and Cuddy finally decided to take  their relationship to the next level, but struggled to find a balance  between their professional and personal lives, and ultimately, Cuddy  made the very emotional decision to end their relationship. As each of  them dealt with the aftermath of the break-up, House got married to an  immigrant in need of a Green Card. In the series' milestone 150th  episode, Thirteen was released from prison after euthanizing her brother  who was suffering from the late stages of Huntington's Disease, the  same disease with which she is afflicted.  As the season comes to a  close, when House's attempts to mend his relationship with Cuddy fall  short, he's compelled to take drastic and possibly irrevocable measures  that could forever change the course of their relationship.", "poster_path": "/tYDeOATjEGDIpyoEaYTrVHH3aj9.jpg", "vote_average": 7.8, "episode_count": 22, "season_number": 8}], "similar": {"page": 1, "results": [{"id": 205, "name": "Garth Marenghi's Darkplace", "adult": false, "overview": "When the Hellmouth opens beneath Darkplace Hospital in downtown Romford, kiddy doctor, Vietnam veteran and ex-warlock Dr. Rick Dagless M.D. is the only man who can close it. Joined by best buddy Dr. Lucien Sanchez, fiery hospital boss Thornton Reed, and woman Liz Asher, Dagless must fight the forces of Darkness while dealing with the burden of day-to-day admin. From the chilling pen of best-selling horror writer Garth Marenghi comes this lost masterpiece of televisual terror. Dare you enter Garth's Darkplace?", "genre_ids": [35, 9648, 10759, 10765], "popularity": 2.331, "vote_count": 167, "poster_path": "/4aSD7ssvpkmNqOxenPiWaLpq4vg.jpg", "vote_average": 8, "backdrop_path": "/iTvtQtqBRB8f7af0BmWcIxNBcf8.jpg", "original_name": "Garth Marenghi's Darkplace", "first_air_date": "2004-01-29", "origin_country": ["GB"], "original_language": "en"}, {"id": 268, "name": "Untold Stories of the ER", "adult": false, "overview": "Doctors recount the most memorable cases they’ve ever encountered. Unusual, touching, humorous or life-changing – no story is too big or too small when it comes to the ER.", "genre_ids": [10759, 18, 10764], "popularity": 4.1137, "vote_count": 21, "poster_path": "/l5hg2Qe15DuAdF2Apey8NKTDpNw.jpg", "vote_average": 8.1, "backdrop_path": "/9mCFfWcOGytwTJlmYvxLY5gXXID.jpg", "original_name": "Untold Stories of the ER", "first_air_date": "2004-04-26", "origin_country": ["US"], "original_language": "en"}, {"id": 658, "name": "The Singing Detective", "adult": false, "overview": "Tormented and bedridden by a debilitating disease, a mystery writer relives his detective stories through his imagination and hallucinations.", "genre_ids": [18], "popularity": 1.8854, "vote_count": 39, "poster_path": "/1xUAh6d239ABRU8KiTqXOijNPuJ.jpg", "vote_average": 7.6, "backdrop_path": "/2slV9gF3070EIRA45SODHnIYsEe.jpg", "original_name": "The Singing Detective", "first_air_date": "1986-11-16", "origin_country": ["GB"], "original_language": "en"}, {"id": 72787, "name": "Patrick Melrose", "adult": false, "overview": "A critical and often humorous look at the upper class, tracking the protagonist's harrowing odyssey from a deeply traumatic childhood through adult substance abuse and, ultimately, toward recovery.", "genre_ids": [18], "popularity": 3.5627, "vote_count": 293, "poster_path": "/t6ubZ1Bpu0elTzA8tT2mxkrfpxA.jpg", "vote_average": 7.543, "backdrop_path": "/u2D2NlCGWi5HwNOJqDMdsvxT2ud.jpg", "original_name": "Patrick Melrose", "first_air_date": "2018-05-12", "origin_country": ["US"], "original_language": "en"}, {"id": 250994, "name": "Ameku M.D.: Doctor Detective", "adult": false, "overview": "Ten’ikai General Hospital’s Supervisory Department of Diagnostic Pathology handles cases other physicians deem too difficult to treat. It’s also where bizarre mysteries surface, from unexplained illnesses to strange murders even the police can’t solve. At the center of it all is Takao Ameku, a brilliant doctor determined to reveal the shocking truth behind these anomalies.", "genre_ids": [16, 9648], "popularity": 3.3232, "vote_count": 23, "poster_path": "/ukyIdEgqRKfovtFm9NzUfrIdm8y.jpg", "vote_average": 7.543, "backdrop_path": "/oBYKvW0VS1L3Gfr81VoJgeK7jzo.jpg", "original_name": "天久鷹央の推理カルテ", "first_air_date": "2025-01-02", "origin_country": ["JP"], "original_language": "ja"}, {"id": 47089, "name": "Nine: Nine Time Travels", "adult": false, "overview": "Park Sun-Woo works as an anchorman at a TV broadcasting station. He is in love with newsreporter Joo Min-Young, who is bright and honest. Park Sun-Woo then obtains 9 incense items, which allows him to go back 20 years in time. Park Sun-Woo travels to the past.", "genre_ids": [18, 10765, 9648], "popularity": 1.7662, "vote_count": 29, "poster_path": "/aPCOCOca8auAP4YTgUzftmVjzMh.jpg", "vote_average": 7.586, "backdrop_path": "/9bMe4R4GW2bXpSQc7h7zSfwmAx2.jpg", "original_name": "나인: 아홉번의 시간여행", "first_air_date": "2013-03-11", "origin_country": ["KR"], "original_language": "ko"}, {"id": 98637, "name": "Pour toujours, plus un jour", "adult": false, "overview": "Chuck has a rare illness and is going to die. He and his girlfriend Delphine decide to take full advantage of the time they have left by doing absolutely everything they want.", "genre_ids": [18, 35], "popularity": 1.043, "vote_count": 1, "poster_path": "/bkTYBuW4pZujZXP5538kZrVvHf1.jpg", "vote_average": 7, "backdrop_path": "/vCa3i2OYiH99cK0TyZW6amM9OcK.jpg", "original_name": "Pour toujours, plus un jour", "first_air_date": "2020-01-22", "origin_country": ["CA"], "original_language": "fr"}, {"id": 72313, "name": "Sick Note", "adult": false, "overview": "When Daniel Glass is misdiagnosed with a fatal disease he begins to notice how everyone around him treats him better. But then he finds out he was misdiagnosed by the most incompetent oncologist on Earth and now he has a big decision to make: come clean and go back to his old rubbish life, or keep pretending to be ill.", "genre_ids": [35, 80], "popularity": 2.2331, "vote_count": 104, "poster_path": "/iB6X3QqgVnwFAJxujK5BnxUbjxx.jpg", "vote_average": 6.649, "backdrop_path": "/vGheNkey14nwT8kGRTqsz8LyWk3.jpg", "original_name": "Sick Note", "first_air_date": "2017-11-07", "origin_country": ["GB"], "original_language": "en"}, {"id": 72380, "name": "Pulse", "adult": false, "overview": "When successful high-flier Frankie Bell is brought crashing to earth by chronic kidney failure she targets an alternate future. Eight years on she is in her second year as a practicing doctor starting her first day in a Renal rotation. Driven to use her second chance to save others, Frankie must confront an ailing health system, and face her toughest challenge - learning to let go.", "genre_ids": [18], "popularity": 1.5006, "vote_count": 12, "poster_path": "/apFmO4sqH5IaC5VwLQMehdNdBkx.jpg", "vote_average": 5.8, "backdrop_path": "/lVOxlGicdNzGEk2JgyAtP54t9Mr.jpg", "original_name": "Pulse", "first_air_date": "2017-07-20", "origin_country": ["AU"], "original_language": "en"}, {"id": 333, "name": "Jewel in the Palace", "adult": false, "overview": "Orphaned Jang-geum becomes the first female physician in the Joseon Dynasty and her determination is tested when people around her start showing their true faces.", "genre_ids": [18], "popularity": 8.9865, "vote_count": 264, "poster_path": "/oiDr9sZPluqKJH8o0vuX5Dh61dh.jpg", "vote_average": 8.511, "backdrop_path": "/mkmlUSTmOb2LI5A6aU1gHaRDElG.jpg", "original_name": "대장금", "first_air_date": "2003-09-15", "origin_country": ["KR"], "original_language": "ko"}, {"id": 250689, "name": "The Farewell Song", "adult": false, "overview": "Ma Zhuo was born in Ya'an, Yucheng. At the age of eight, She was taken to Chengdu by her mother Lin Guoguo to live together. She grew up with Xia Gang's son Xia Ze. The two childhood sweethearts became each other's first love. Lin Guoguo and Xia Gang were accidentally involved in a strange murder. From then on, Ma Zhuo and Xia Ze were emotionally displaced, and their fate was tortuous, pursuing the truth of their fathers in danger and thorns.", "genre_ids": [18, 9648], "popularity": 1.1235, "vote_count": 1, "poster_path": "/nx6gAgLAcMUyStTClDrdsUBy4zJ.jpg", "vote_average": 6, "backdrop_path": "/dWDr5gqpsAzodm6k8Vtx5bjqwIY.jpg", "original_name": "离歌", "first_air_date": "2024-03-31", "origin_country": ["CN"], "original_language": "zh"}, {"id": 547, "name": "Medical Investigation", "adult": false, "overview": "An elite team of medical experts of the National Institutes of Health investigates unusual public-health crises, such as sudden outbreaks of serious and mysterious diseases.", "genre_ids": [18, 9648], "popularity": 3.5943, "vote_count": 15, "poster_path": "/3bTy80VccV3suS9ywXryGakdG5y.jpg", "vote_average": 6.5, "backdrop_path": "/db5EzXlDr6LGK0LctVLP9LOxivJ.jpg", "original_name": "Medical Investigation", "first_air_date": "2004-09-09", "origin_country": ["US"], "original_language": "en"}, {"id": 46135, "name": "Hatsukoi", "adult": false, "overview": "Midori is a married woman with a happy home life, a child, and a job as a speech therapist. One day, Midori is diagnosed with liver cancer and finds herself face to face with her first love; a man whose betrayal had left her deeply scarred. They are forced to put their past aside and work together to save her life.", "genre_ids": [18], "popularity": 0.7508, "vote_count": 0, "poster_path": "/a1RdGcz0XF9VpyndovQB2J519sV.jpg", "vote_average": 0, "backdrop_path": "/ebjJICSBxGpyFeIyGdsxnZep0s0.jpg", "original_name": "はつ恋", "first_air_date": "2012-05-22", "origin_country": ["JP"], "original_language": "ja"}, {"id": 46161, "name": "Vale Tudo", "adult": false, "overview": "Fátima Accioly is a young, callous woman who wants to be rich and successful at any price. After selling her family's house in the country, she heads to Rio and gets to know dress man César who is unscrupulous himself. Meanwhile, her mother Raquel stays behind without home and money, but finally tries to find her daughter in the big city. Both women come in contact with the rich Roitman family which changes their lives forever.", "genre_ids": [10766, 18], "popularity": 8.7624, "vote_count": 24, "poster_path": "/mDcRbUmRtri8ibccK19C9vYslxF.jpg", "vote_average": 8.6, "backdrop_path": "/vrlZvHqAV2iNgacLTDBLdsx11SP.jpg", "original_name": "Vale Tudo", "first_air_date": "1988-05-16", "origin_country": ["BR"], "original_language": "pt"}, {"id": 46242, "name": "Becoming a Doctor at Age 37", "adult": false, "overview": "The drama portrays the hard struggles of a 37-year-old man who decided to quit his job as a salaryman at a food company and is now working as a medical intern at a university hospital.", "genre_ids": [18], "popularity": 0.9583, "vote_count": 2, "poster_path": "/xQcTnoZzxkmmioHaTPgyMAUEdC2.jpg", "vote_average": 6.5, "backdrop_path": null, "original_name": "37歳で医者になった僕", "first_air_date": "2012-04-10", "origin_country": ["JP"], "original_language": "ja"}, {"id": 24, "name": "Presidio Med", "adult": false, "overview": "Presidio Med is an American medical drama that aired on CBS from September 2002, to January 2003. The series centers on a San Francisco hospital. It was created by John Wells and Lydia Woodward, who also created ER.", "genre_ids": [18], "popularity": 2.1824, "vote_count": 4, "poster_path": "/dpsbrvlgr48nshG1MS8i2saaINQ.jpg", "vote_average": 8, "backdrop_path": "/rU36ztMT9kNw8LZGlO3DNoOqu2X.jpg", "original_name": "Presidio Med", "first_air_date": "2002-09-24", "origin_country": ["US"], "original_language